function slugify(value: string) { return value.toLowerCase().replace(/&/g, "and").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""); }
function grade(score: number): CareerGrade {
  const values: Array<[number, CareerGrade]> = [[92,"A+"],[86,"A"],[80,"A-"],[74,"B+"],[68,"B"],[62,"B-"],[56,"C+"],[50,"C"],[44,"C-"],[38,"D+"],[32,"D"],[26,"D-"]];
  return values.find(([minimum]) => score >= minimum)?.[1] ?? "F";
}
export function careerGradeLabel(value: CareerGrade) { return value.startsWith("A") ? value === "A+" ? "Exceptional" : "Very strong" : value.startsWith("B") ? "Above average" : value.startsWith("C") ? "Mixed" : value.startsWith("D") ? "Weak" : "Very weak"; }
function result(score: number, explanation: string, factors: string[]): CareerGradeResult { const value = grade(Math.max(0, Math.min(100, score))); return { grade: value, label: careerGradeLabel(value), explanation, factors }; }
function buildGrades(profile: Profile, domain: Domain): CareerRecord["grades"] {
  const midpoint = (profile.hours[0] + profile.hours[1]) / 2;
  const compensation = profile.salary ? Math.min(98, 35 + profile.salary / 2500) : 50;
  const market = Math.max(18, Math.min(98, 51 + profile.growth * 2.15));
  const workLife = Math.max(25, Math.min(94, 116 - midpoint * 1.25));
  const educationPenalty = /Doctor|professional|Law degree/.test(profile.education) ? 31 : /Master/.test(profile.education) ? 20 : /Bachelor/.test(profile.education) ? 10 : 0;
  const access = 96 - educationPenalty - domain.competition * .42;
  const resilience = 37 + domain.factors.physical * 9 + domain.factors.trust * 7 + domain.factors.accountability * 6 + domain.factors.interpersonal * 6 + domain.factors.judgment * 7 - domain.factors.routine * 8 - domain.factors.digital * 4;
  const upside = 35 + domain.factors.complementarity * 13 + domain.factors.digital * 8 + Math.max(0, profile.growth) * .4;
  const stability = domain.stability + Math.max(-10, Math.min(10, profile.growth));
  const outlook = market * .32 + stability * .24 + resilience * .2 + upside * .24;
  return {
    compensation: result(compensation, profile.salary ? `The ${profile.basisTitle.toLowerCase()} U.S. median is ${new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:0}).format(profile.salary)}.` : "A reliable occupation-level U.S. figure is not available.", ["BLS U.S. median wage", profile.basisTitle]),
    jobMarket: result(market, `BLS projects ${profile.growth}% employment change for the mapped occupation from 2024 to 2034.`, ["BLS 2024–34 projection", `${profile.growth}% projected change`]),
    workLife: result(workLife, `Typical schedules are estimated around ${profile.hours[0]}–${profile.hours[1]} hours, with substantial employer variation.`, ["Typical weekly-hours range", "Schedule predictability and stress burden"]),
    entryAccessibility: result(access, `Entry reflects ${profile.education.toLowerCase()} and the field’s recruiting competition.`, [profile.education, "Recruiting competition", "Licensure where applicable"]),
    stability: result(stability, "Stability combines current occupational demand with the durability and accountability of the work.", ["Economic necessity", "Regulatory or operational accountability", "BLS demand direction"]),
    aiResilience: result(resilience, "Resilience reflects how much core value depends on physical presence, trust, accountability, interpersonal work, and non-routine judgment.", ["Task routineness", "Physical presence", "Human trust", "Accountable judgment"]),
    aiUpside: result(upside, "Upside reflects how strongly AI tools could accelerate analysis, drafting, design, or technical work while people retain responsibility.", ["Digital-task share", "Technical complementarity", "Demand for validated outputs"]),
    longTermOutlook: result(outlook, `Current evidence suggests a ${profile.growth >= 8 ? "growing" : profile.growth < 0 ? "contracting" : "broadly steady"} market over the next decade, shaped by demand, skill supply, and task-level AI change.`, ["Job market", "Career stability", "AI resilience", "AI upside"]),
  };
}
