function intensity(domain: Domain, domainKey: string, name: string): CareerRecord["intensity"] {
  const veryQuant = /Quant|Statistic|Actuar|Operations Research|Cryptograph|Computational/.test(name);
  const veryCode = /Software|Developer|Machine Learning|AI Engineer|Quant Developer|Data Engineer/.test(name);
  return { quantitative: veryQuant ? "Very High" : domain.intensity.quantitative, coding: veryCode ? "Very High" : domain.intensity.coding, writing: ["law","creative","public","research","education"].includes(domainKey) ? "High" : "Moderate", people: domain.intensity.people, research: ["research","data"].includes(domainKey) ? "High" : "Moderate", creativity: domainKey === "creative" ? "Very High" : ["technology","research","engineering"].includes(domainKey) ? "High" : "Moderate", physical: domainKey === "skilled" ? "Very High" : ["healthcare","engineering"].includes(domainKey) ? "Moderate" : "Low" };
}

