  const settings = extra.settings ?? (domainKey === "healthcare" ? ["Hospitals or clinics", "Patient-care settings"] : domainKey === "research" ? ["Laboratories", "Universities, government, or R&D organizations"] : domainKey === "education" ? ["Classrooms", "Schools or education programs"] : domainKey === "skilled" ? ["Customer sites", "Construction or industrial facilities"] : domainKey === "engineering" ? ["Offices and design environments", "Labs, plants, or project sites"] : ["Office or hybrid environments", "Remote work where employer and work allow"]);
  const schedule = extra.schedule ?? (profile.hours[1] >= 60 ? "Deadline- or client-driven with frequent peaks" : domainKey === "healthcare" ? "Setting-dependent; may include shifts, nights, or weekends" : domainKey === "skilled" ? "Site-based; overtime or emergency calls vary" : profile.hours[1] > 50 ? "Variable around deadlines and peak periods" : "Generally predictable with employer- and project-specific peaks");
